import { StatusBar } from 'expo-status-bar'
import { useVideoPlayer, VideoView } from 'expo-video'
import { useEffect } from 'react'
import { StyleSheet, View, AppState } from 'react-native'
import {
	interpolate,
	interpolateColor,
	useAnimatedStyle,
	useSharedValue,
	withDelay,
	withSpring
} from 'react-native-reanimated'
import { SPLASH_SCREEN_TRANSITION_DELAY } from '@/constants'
import { SignUpButtonContainer } from './components/SignUpButtonContainer'
import { HeaderContainer } from './components/HeaderContainer'
import { defineStyles } from '@/utils/defineStyles'
import { colors } from '@/theme'
import { LinearGradient } from 'expo-linear-gradient'
const anythingVideo = require('./assets/videos/sign-up.mp4')

export const SignUpScreen = () => {
	const logoAnimation = useSharedValue(0)
	const titleAnimation = useSharedValue(-100)
	const appleLoginButton = useSharedValue(400)
	const googleLoginButton = useSharedValue(600)
	const emailLoginButton = useSharedValue(800)

	const player = useVideoPlayer(anythingVideo, (p) => {
		p.loop = true
		p.muted = true
		p.audioMixingMode = 'mixWithOthers'
		p.showNowPlayingNotification = false
		p.play()
	})

	useEffect(() => {
		// listen to app state change and resume video when app comes to foreground
		const subscription = AppState.addEventListener('change', (nextAppState) => {
			if (nextAppState === 'active') {
				player.play()
			}
		})

		return () => subscription.remove()
	}, [player])

	useEffect(() => {
		logoAnimation.set(
			withDelay(
				SPLASH_SCREEN_TRANSITION_DELAY,
				withSpring(220, { duration: 1100, dampingRatio: 1 })
			)
		)
		titleAnimation.set(
			withDelay(
				SPLASH_SCREEN_TRANSITION_DELAY,
				withSpring(148, { duration: 1100, dampingRatio: 1 })
			)
		)
		googleLoginButton.set(
			withDelay(
				SPLASH_SCREEN_TRANSITION_DELAY,
				withSpring(0, { duration: 1100, dampingRatio: 1 })
			)
		)
		appleLoginButton.set(
			withDelay(
				SPLASH_SCREEN_TRANSITION_DELAY,
				withSpring(0, { duration: 1300, dampingRatio: 1 })
			)
		)
		emailLoginButton.set(
			withDelay(
				SPLASH_SCREEN_TRANSITION_DELAY,
				withSpring(0, { duration: 1500, dampingRatio: 1 })
			)
		)
	}, [
		logoAnimation,
		titleAnimation,
		appleLoginButton,
		googleLoginButton,
		emailLoginButton
	])

	const logoStyle = useAnimatedStyle(() => ({
		transform: [
			{ translateY: -logoAnimation.get() },
			{ scale: interpolate(logoAnimation.get(), [0, 100], [1, 0.8]) }
		],
		color: interpolateColor(logoAnimation.get(), [0, 100], ['#dbdbdb', '#fff'])
	}))

	const titleStyle = useAnimatedStyle(() => ({
		transform: [{ translateY: -titleAnimation.get() }]
	}))

	const appleLoginButtonStyle = useAnimatedStyle(() => ({
		transform: [{ translateY: appleLoginButton.get() }]
	}))

	const googleLoginButtonStyle = useAnimatedStyle(() => ({
		transform: [{ translateY: googleLoginButton.get() }]
	}))

	const emailLoginButtonStyle = useAnimatedStyle(() => ({
		transform: [{ translateY: emailLoginButton.get() }]
	}))

	return (
		<>
			<StatusBar style="light" />
			<View style={styles.screenContainer}>
				<View
					style={{
						width: '100%',
						height: '70%',
						position: 'absolute',
						top: 0,
						left: 0,
						right: 0,
						bottom: 0
					}}
				>
					<VideoView
						style={{
							height: '100%',
							width: '100%',
							position: 'absolute'
						}}
						contentFit="cover"
						player={player}
						nativeControls={false}
					/>
					<LinearGradient
						colors={[`${colors.light.gray[25]}00`, colors.light.gray[25]]}
						style={{
							position: 'absolute',
							left: 0,
							right: 0,
							bottom: 0,
							height: 140
						}}
					/>
				</View>

				<HeaderContainer logoStyle={logoStyle} titleStyle={titleStyle} />

				<SignUpButtonContainer
					appleLoginButtonStyle={appleLoginButtonStyle}
					googleLoginButtonStyle={googleLoginButtonStyle}
					emailLoginButtonStyle={emailLoginButtonStyle}
				/>
			</View>
		</>
	)
}

const styles = defineStyles({
	background: {
		...StyleSheet.absoluteFillObject,
		height: 560
	},
	screenContainer: {
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center',
		backgroundColor: colors.light.gray[25]
	},
	logoContainer: {
		...StyleSheet.absoluteFillObject,
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center',
		gap: 4
	},
	logo: {
		width: 72,
		height: 75
	},
	title: {
		fontSize: 28,
		color: '#fff',
		textAlign: 'center'
	},
	authContainer: {
		position: 'absolute',
		bottom: 124,
		left: 0,
		right: 0,
		flexDirection: 'row',
		justifyContent: 'center',
		alignItems: 'center',
		width: '100%',
		gap: 24
	},
	authButtonContainer: {
		borderColor: '#fff',
		borderWidth: 2,
		borderRadius: 100,
		width: 92,
		height: 92,
		justifyContent: 'center',
		alignItems: 'center'
	},
	authButtonIcon: {
		width: 30,
		height: 30
	}
})
